SELECT json_build_object('table',table_name,'columns',json_agg(column_name ORDER BY ordinal_position)) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('teams','leagues','meta') GROUP BY table_name;
SELECT json_build_object('sport',sport,'teams',count(*),'gender_key',count(*) FILTER(WHERE meta ? 'gender'),'team_gender_key',count(*) FILTER(WHERE meta ? 'team_gender'),'raw_gender_key',count(*) FILTER(WHERE raw_response ? 'gender')) FROM public.teams GROUP BY sport ORDER BY sport;
SELECT json_build_object('meta_key',k,'teams',count(*)) FROM public.teams CROSS JOIN LATERAL jsonb_object_keys(COALESCE(meta,'{}'::jsonb)) k WHERE k ~* 'gender|sex|women|men|category' GROUP BY k ORDER BY k;
SELECT json_build_object('id',id,'sport',sport,'name',name,'gender',meta->>'gender','team_gender',meta->>'team_gender') FROM public.teams WHERE name ILIKE '%chelsea%' OR name ILIKE '%women%' ORDER BY sport,id LIMIT 12;
SELECT json_build_object('created_at',created_at,'model',receipt#>>'{measurement,response,model}','subject_meta',receipt#>'{measurement,request,state,subject_meta}') FROM public.classifier_measurements WHERE receipt#>>'{measurement,request,state,subject_meta,identity,entity_type}'='team' ORDER BY id DESC LIMIT 3;
SELECT json_build_object('headline',headline,'candidates',public.classifier_identity_candidates('FOOTBALL',headline,'')) FROM (VALUES ($$Chelsea Women appoint Jo Vale as head coach$$),($$Chelsea's women's team appoint Jo Vale as head coach$$),($$Chelsea men's team appoint Jo Vale as head coach$$)) cases(headline);
SELECT json_build_object('league_gender_key',count(*) FILTER(WHERE meta ? 'gender'),'league_team_gender_key',count(*) FILTER(WHERE meta ? 'team_gender'),'leagues',count(*)) FROM public.leagues;
